INSERT INTO arelore_education.user_detection_type
(type_code, type_name, type_description, extra_info)
VALUES
    ('RK_SA_ARCH_2015H2_GK', '软考-系统架构设计师-2015年下半年-综合知识', '全国计算机技术与软件专业技术资格（水平）考试 系统架构设计师 2015年下半年 综合知识试题与解析', '{"source":"2015年下半年 系统架构设计师 答案详解 .docx","exam":"系统架构设计师","year":"2015","term":"下半年","session":"综合知识","questionCount":75,"scoring":{"resultMode":"objective_sum","scoreDimension":"score","maxScore":75,"scoringVersion":"1.0"},"resultMeanings":{}}')
ON DUPLICATE KEY UPDATE
                     type_name = VALUES(type_name),
                     type_description = VALUES(type_description),
                     extra_info = VALUES(extra_info);

INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
VALUES
    ('RK_SA_ARCH_2015H2_GK', 'RK_SA_ARCH_2015H2_GK_Q001', '某航空公司机票销售系统有n个售票点，该系统为每个售票点创建一个进程Pi（i=1，2，…，n）管理机票销售。假设Tj（j=1，2，…，m）单元存放某日某航班的机票剩余票数，Temp为Pi进程的临时工作单元，x为某用户的订票张数。初始化时系统应将信号量S赋值为（1）。Pi进程的工作流程如下图所示，若用P操作和V操作实现进程间的同步与互斥，则图中空(a)，空(b)和空(c)处应分别填入（2）。…', 1, '单选题', '[{"key":"A","text":"0","scores":{"score":0}},{"key":"B","text":"1","scores":{"score":1}},{"key":"C","text":"2","scores":{"score":0}},{"key":"D","text":"3","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":1,"correctOptionKey":"B","explanation":"本题考査PV操作方面的基本知识。\\n试题(1)的正确答案是B，因为公共数据单元是一个临界资源，最多允许1个终端进程使用，因此需要设置一个互斥信号量S，初值等于1。\\n试题(2)的正确答案是A，因为进入临界区时执行P操作，退出临界区时执行V操作。\\n\\n假设系统采用段式存储管理方法，进程P的段表如下所示。逻辑地址（3）不能转换为对应的物理地址；不能转换为对应的物理地址的原因是进行（4）。\\n 【img:22efecaa9fc3785c12e3fec04d04dfc4ce4b4970e088cef755a9766c5ca38efa】","imageHashValues":["88f0df97857b629f08d303d898a6fc792046e9b2358d7545e20394d763cdeff0","22efecaa9fc3785c12e3fec04d04dfc4ce4b4970e088cef755a9766c5ca38efa"],"fullQuestionName":"某航空公司机票销售系统有n个售票点，该系统为每个售票点创建一个进程Pi（i=1，2，…，n）管理机票销售。假设Tj（j=1，2，…，m）单元存放某日某航班的机票剩余票数，Temp为Pi进程的临时工作单元，x为某用户的订票张数。初始化时系统应将信号量S赋值为（1）。Pi进程的工作流程如下图所示，若用P操作和V操作实现进程间的同步与互斥，则图中空(a)，空(b)和空(c)处应分别填入（2）。\\n 【img:88f0df97857b629f08d303d898a6fc792046e9b2358d7545e20394d763cdeff0】","fullExplanation":"本题考査PV操作方面的基本知识。\\n试题(1)的正确答案是B，因为公共数据单元是一个临界资源，最多允许1个终端进程使用，因此需要设置一个互斥信号量S，初值等于1。\\n试题(2)的正确答案是A，因为进入临界区时执行P操作，退出临界区时执行V操作。\\n\\n假设系统采用段式存储管理方法，进程P的段表如下所示。逻辑地址（3）不能转换为对应的物理地址；不能转换为对应的物理地址的原因是进行（4）。\\n 【img:22efecaa9fc3785c12e3fec04d04dfc4ce4b4970e088cef755a9766c5ca38efa】"}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
                     extra_info = VALUES(extra_info);

