VALUES
    ('RK_SA_ARCH_2015H2_GK', 'RK_SA_ARCH_2015H2_GK_Q021', '电子商务系统中参与电子商务活动的实体包括（21）。', 21, '单选题', '[{"key":"A","text":"客户、商户、银行和认证中心","scores":{"score":1}},{"key":"B","text":"客户、银行、商户和政府机构","scores":{"score":0}},{"key":"C","text":"客户、商户、银行和物流企业","scores":{"score":0}},{"key":"D","text":"客户、商户、政府和物流企业","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":21,"correctOptionKey":"A","explanation":"本题考查电子商务方面的基础知识。\\n电子商务分五个方面，即电子商情广告、电子选购与交易、电子交易凭证.的交换、电子支付与结算，以及网上售后服务等。参与电子商务的实体有4类：客户(个人消费者或集团购买)、商户(包括销售商、制造商和储运商)、银行(包括发行和收单行)及认证中心。","imageHashValues":[]}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
