INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
VALUES
    ('RK_SA_ARCH_2015H2_GK', 'RK_SA_ARCH_2015H2_GK_Q034', 'RUP强调采用（34）的方式来开发软件，这样做的好处是（35）。', 34, '单选题', '[{"key":"A","text":"原型和螺旋","scores":{"score":0}},{"key":"B","text":"螺旋和增量","scores":{"score":0}},{"key":"C","text":"迭代和增量","scores":{"score":1}},{"key":"D","text":"快速和迭代","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":34,"correctOptionKey":"C","explanation":"RUP将项目管理、业务建模、分析与设计等统一起来，贯穿整个开发过程。RUP中的软件过程在时间上被分解为4个顺序的阶段，分别是初始阶段、细化阶段、构建阶段和移交阶段。每个阶段结束时都要安排一次技术评审，以确定这个阶段的目标是否已经满足。如果评审结果令人满意，就可以允许项目进入下一个阶段。可以看出，基于RUP的软件过程是一个迭代和增量的过程。通过初始、细化、构建和移交4个阶段就是一个开发周期，每次经过这4个阶段就会产生一代软件。除非产品退役，否则通过重复同样的4个阶段，产品将演化为下一代产品，但每一次的侧重点都将放在不同的阶段上。这样做的好处是在软件开发的早期就可以对关键的、影响大的风险进行处理。","imageHashValues":[],"fullExplanation":"RUP将项目管理、业务建模、分析与设计等统一起来，贯穿整个开发过程。RUP中的软件过程在时间上被分解为4个顺序的阶段，分别是初始阶段、细化阶段、构建阶段和移交阶段。每个阶段结束时都要安排一次技术评审，以确定这个阶段的目标是否已经满足。如果评审结果令人满意，就可以允许项目进入下一个阶段。可以看出，基于RUP的软件过程是一个迭代和增量的过程。通过初始、细化、构建和移交4个阶段就是一个开发周期，每次经过这4个阶段就会产生一代软件。除非产品退役，否则通过重复同样的4个阶段，产品将演化为下一代产品，但每一次的侧重点都将放在不同的阶段上。这样做的好处是在软件开发的早期就可以对关键的、影响大的风险进行处理。"}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
                     extra_info = VALUES(extra_info);

