INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
VALUES
    ('RK_SA_ARCH_2015H2_GK', 'RK_SA_ARCH_2015H2_GK_Q042', '软件架构是降低成本、改进质量、按时和按需交付产品的关键因素。软件架构设计需满足系统的（42），如性能、安全性和可修改性等，并能够指导设计人员和实现人员的工作。', 42, '单选题', '[{"key":"A","text":"功能需求","scores":{"score":0}},{"key":"B","text":"性能需求","scores":{"score":0}},{"key":"C","text":"质量属性","scores":{"score":1}},{"key":"D","text":"业务属性","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":42,"correctOptionKey":"C","explanation":"本题考查软件架构设计方面的基础知识。\\n软件架构是降低成本、改进质量、按时和按需交付产品的关键因素，软件架构设计需要满足系统的质量属性，如性能、安全性和可修改性等，软件架构设计需要确定组件之间的依赖关系，支持项目计划和管理活动，软件架构能够指导设计人员和实现人员的工作。一般在设计软件架构之初，会根据用户需求，确定多个候选架构，并从中选择一个较优的架构，并随着软件的开发，对这个架构进行微调，以达到最佳效果。","imageHashValues":[]}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
                     extra_info = VALUES(extra_info);

INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
VALUES
    ('RK_SA_ARCH_2015H2_GK', 'RK_SA_ARCH_2015H2_GK_Q043', '架构描述语言(Architecture Description Language，ADL）是一种为明确说明软件系统的概念架构和对这些概念架构建模提供功能的语言。ADL主要包括以下组成部分：组件、组件接口、（43）和架构配置。', 43, '单选题', '[{"key":"A","text":"架构风格","scores":{"score":0}},{"key":"B","text":"架构实现","scores":{"score":0}},{"key":"C","text":"连接件","scores":{"score":1}},{"key":"D","text":"组件约束","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":43,"correctOptionKey":"C","explanation":"本题考查架构描述语言的理解与掌握。\\n架构描述语言(Architecture Description Language，ADL)是一种为明确说明软件系统的概念架构和对这些概念架构建模提供功能的语言。ADL主要包括以下组成部分：组件、组件接口、连接件和架构配置。ADL对连接件的重视成为区分ADL和其他建模语言的重要特征之一。","imageHashValues":[]}')
